import { useState, useEffect } from 'react';
import { ethers, Contract, BrowserProvider } from 'ethers';

const STAKING_ABI = [
  'function getStakerInfo(address user) public view returns (uint256 balance, uint256 staked, uint256 rewards)',
  'event Staked(address indexed user, uint256 amount)',
  'event Withdrawn(address indexed user, uint256 amount)',
];

const STAKING_ADDRESS = process.env.NEXT_PUBLIC_STAKING_ADDRESS;

export interface StakerInfo {
  address: string;
  balance: string;
  staked: string;
  rewards: string;
  total: string; // balance + staked
  rank: number;
}

export function useLeaderboard() {
  const [leaderboard, setLeaderboard] = useState<StakerInfo[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchLeaderboard = async () => {
      try {
        setLoading(true);
        const provider = new ethers.JsonRpcProvider(
          process.env.NEXT_PUBLIC_RPC_URL
        );

        const stakingContract = new Contract(
          STAKING_ADDRESS!,
          STAKING_ABI,
          provider
        );

        // Escucha eventos de Staked para obtener lista de stakers
        const filter = stakingContract.filters.Staked();
        const events = await provider.getLogs({
          address: STAKING_ADDRESS,
          topics: filter.topics,
          fromBlock: 'latest',
        });

        // Extrae direcciones únicas de los eventos
        const stakers = new Set<string>();
        events.forEach((event) => {
          const decoded = stakingContract.interface.parseLog(event);
          if (decoded) {
            stakers.add(decoded.args[0]);
          }
        });

        // Obtén info de cada staker
        const stakerInfoList: StakerInfo[] = [];
        for (const stakerAddress of Array.from(stakers)) {
          try {
            const [balance, staked, rewards] = 
              await stakingContract.getStakerInfo(stakerAddress);

            const balanceStr = ethers.formatUnits(balance, 18);
            const stakedStr = ethers.formatUnits(staked, 18);
            const rewardsStr = ethers.formatUnits(rewards, 18);
            const totalStr = (
              parseFloat(balanceStr) + parseFloat(stakedStr)
            ).toString();

            stakerInfoList.push({
              address: stakerAddress,
              balance: balanceStr,
              staked: stakedStr,
              rewards: rewardsStr,
              total: totalStr,
              rank: 0,
            });
          } catch (err) {
            console.error(`Error fetching info for ${stakerAddress}:`, err);
          }
        }

        // Ordena por total staked (mayor a menor)
        stakerInfoList.sort((a, b) => 
          parseFloat(b.total) - parseFloat(a.total)
        );

        // Asigna ranks
        stakerInfoList.forEach((staker, index) => {
          staker.rank = index + 1;
        });

        setLeaderboard(stakerInfoList.slice(0, 10)); // Top 10
        setError(null);
      } catch (err) {
        console.error('Error fetching leaderboard:', err);
        setError('Error cargando el leaderboard');
      } finally {
        setLoading(false);
      }
    };

    // Fetch inicial
    fetchLeaderboard();

    // Refetch cada 10 segundos
    const interval = setInterval(fetchLeaderboard, 10000);

    return () => clearInterval(interval);
  }, []);

  return { leaderboard, loading, error };
}
