'use client';

import { useLeaderboard, StakerInfo } from '@/hooks/useLeaderboard';

const getMedalEmoji = (rank: number) => {
  if (rank === 1) return '🥇';
  if (rank === 2) return '🥈';
  if (rank === 3) return '🥉';
  return `#${rank}`;
};

const shortenAddress = (addr: string) => {
  return `${addr.slice(0, 6)}...${addr.slice(-4)}`;
};

export function LeaderboardTable() {
  const { leaderboard, loading, error } = useLeaderboard();

  if (loading) {
    return (
      <div className="flex justify-center items-center h-96">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-cyan-500 border-solid"></div>
        <span className="ml-4 text-cyan-400 font-bold">Cargando ranking...</span>
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-red-900 border border-red-500 p-4 rounded-lg text-red-100">
        ⚠️ {error}
      </div>
    );
  }

  return (
    <div className="overflow-x-auto">
      <table className="w-full text-left border-collapse">
        <thead>
          <tr className="border-b-2 border-cyan-500">
            <th className="px-4 py-3 text-cyan-400 font-bold">Rank</th>
            <th className="px-4 py-3 text-cyan-400 font-bold">Wallet</th>
            <th className="px-4 py-3 text-green-400 font-bold text-right">Balance</th>
            <th className="px-4 py-3 text-blue-400 font-bold text-right">Stakeado</th>
            <th className="px-4 py-3 text-yellow-400 font-bold text-right">Rewards</th>
            <th className="px-4 py-3 text-cyan-400 font-bold text-right">Total</th>
          </tr>
        </thead>
        <tbody>
          {leaderboard.map((staker, index) => (
            <tr
              key={staker.address}
              className={`border-b border-gray-700 hover:bg-gray-800 transition ${
                index === 0 ? 'bg-yellow-900 bg-opacity-20' : ''
              }`}
            >
              <td className="px-4 py-4">
                <span className="text-lg font-bold">
                  {getMedalEmoji(staker.rank)}
                </span>
              </td>
              <td className="px-4 py-4 font-mono text-sm text-gray-300">
                {shortenAddress(staker.address)}
              </td>
              <td className="px-4 py-4 text-right text-green-400 font-semibold">
                {parseFloat(staker.balance).toFixed(2)} NXT
              </td>
              <td className="px-4 py-4 text-right text-blue-400 font-semibold">
                {parseFloat(staker.staked).toFixed(2)} NXT
              </td>
              <td className="px-4 py-4 text-right text-yellow-400 font-semibold">
                {parseFloat(staker.rewards).toFixed(2)} NXT
              </td>
              <td className="px-4 py-4 text-right text-cyan-400 font-bold text-lg">
                {parseFloat(staker.total).toFixed(2)} NXT
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      {leaderboard.length === 0 && (
        <div className="text-center py-8 text-gray-400">
          📊 Sin stakers aún. ¡Sé el primero!
        </div>
      )}
    </div>
  );
}
